import {sampleKeys,keySegment} from './keyframes.js';
import {validEasing} from './easing.js';
export const FIELD_NAMES={wind:'기류',suction:'흡인'};
export const rotate=(v,q)=>{const [x,y,z,w]=q,[a,b,c]=v,tx=2*(y*c-z*b),ty=2*(z*a-x*c),tz=2*(x*b-y*a);return [a+w*tx+y*tz-z*ty,b+w*ty+z*tx-x*tz,c+w*tz+x*ty-y*tx];};
export function fieldPose(f,time,toQuat){const pose=sampleKeys(f,time,toQuat),{a,b,t}=keySegment(f,time);return {...pose,size:a.size.map((v,i)=>v+(b.size[i]-v)*t)};}
export function fieldForce(f,pose,position,velocity=[0,0,0],mass=1,gravity=0,targetVelocity=[0,0,0]){const delta=position.map((v,i)=>v-pose.p[i]),local=rotate(delta,[-pose.q[0],-pose.q[1],-pose.q[2],pose.q[3]]);if(f.kind==='wind'){if(local.some((v,i)=>Math.abs(v)>pose.size[i]/2))return [0,0,0];return rotate([0,0,f.strength],pose.q);}const distance=Math.hypot(...delta),soft=Math.max(.1,Math.min(...pose.size)*.1),spread=local[2]/pose.size[2],inside=local[2]>=0&&local[2]<=pose.size[2]&&Math.hypot(local[0]/(pose.size[0]/2),local[1]/(pose.size[1]/2))<=spread;if(f.strength<=0||!inside&&distance>soft)return [0,0,0];const stiffness=Math.min(f.strength/soft,mass*900),pull=Math.min(f.strength,stiffness*distance),damping=2*Math.sqrt(mass*(distance>.0001?pull/distance:stiffness)),hold=1-Math.min(1,Math.max(0,distance/soft-1));return delta.map((v,i)=>-(distance>.0001?v/distance*pull:0)-damping*(velocity[i]-targetVelocity[i])+(i===1?mass*gravity*hold:0));}

export function validateFields(p){const num=(v,a,b)=>typeof v==='number'&&Number.isFinite(v)&&v>=a&&v<=b,vec=(v,a,b)=>Array.isArray(v)&&v.length===3&&v.every(n=>num(n,a,b)),ids=new Set();if(!Array.isArray(p.fields||[])||(p.fields||[]).length>32)throw new Error('기류·흡인 영역은 32개까지 지원합니다.');for(const f of p.fields||[]){if(!/^v[1-9]\d{0,5}$/.test(f.id)||ids.has(f.id)||!FIELD_NAMES[f.kind])throw new Error('동작 영역 ID 또는 종류가 잘못되었습니다.');ids.add(f.id);if(f.continuous!=null&&typeof f.continuous!=='boolean')throw new Error('영역의 계속 작동 설정이 잘못되었습니다.');if(!vec(f.position,-4096,4096)||!vec(f.rotation,-3600,3600)||!vec(f.size,.05,128)||!num(f.time,0,p.duration)||!num(f.duration,.05,Number.MAX_SAFE_INTEGER/120)||!num(f.strength,0,100000))throw new Error('동작 영역 값이 지원 범위를 벗어났습니다.');const times=new Set();if(!Array.isArray(f.keys||[])||(f.keys||[]).length>64)throw new Error('영역 키프레임은 64개까지 지원합니다.');for(const k of f.keys||[]){if(!validEasing(k.easing)||!num(k.time,0,p.duration)||times.has(k.time)||!vec(k.position,-4096,4096)||!vec(k.rotation,-3600,3600)||!vec(k.size,.05,128))throw new Error('영역 키프레임이 잘못되었거나 시점이 중복됩니다.');times.add(k.time);}}}
export function magneticForce(a,b,pa,pb){const ma=a.magnet||{},mb=b.magnet||{},pole=m=>['north','south'].includes(m.polarity)&&m.strength>0;if(!pole(ma)&&!pole(mb)||!ma.polarity||ma.polarity==='off'||!mb.polarity||mb.polarity==='off'||ma.polarity==='metal'&&mb.polarity==='metal')return [0,0,0];const range=Math.max(pole(ma)?ma.range:0,pole(mb)?mb.range:0),d=pb.map((v,i)=>v-pa[i]),dist=Math.hypot(...d);if(dist<.02||dist>=range)return [0,0,0];const strength=pole(ma)&&pole(mb)?Math.sqrt(ma.strength*mb.strength):pole(ma)?ma.strength:mb.strength,sign=ma.polarity===mb.polarity?-1:1,force=Math.min(strength/Math.max(.25,dist*dist)*(1-dist/range)**2,Math.min(a.mass,b.mass)*100);return d.map(v=>v/dist*force*sign);}
export function magneticPairs(entries){const poles=entries.filter(e=>['north','south'].includes(e.o.magnet?.polarity)&&e.o.magnet.strength>0);if(!poles.length)return [];const cell=Math.max(1,...poles.map(e=>e.o.magnet.range)),grid=new Map(),key=p=>p.map(v=>Math.floor(v/cell));for(const e of entries){const k=key(e.p).join(',');if(!grid.has(k))grid.set(k,[]);grid.get(k).push(e);}const pairs=[],seen=new Set();for(const a of poles){const k=key(a.p);for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)for(let z=-1;z<=1;z++)for(const b of grid.get([k[0]+x,k[1]+y,k[2]+z].join(','))||[]){if(a===b)continue;const id=[a.o.id,b.o.id].sort().join(':');if(seen.has(id))continue;seen.add(id);pairs.push([a,b]);}}return pairs;}
